Subroutine Saludar(nombre As String)
  Write "Hola, ", nombre;
EndSubroutine

Subroutine Doble(n As Integer) As Integer
  Return n * 2;
EndSubroutine

Algorithm Principal
  Saludar("Ana");
  Write Doble(21);
EndAlgorithm

Function area <- AreaRectangulo(base As Real, alto As Real)
  Define area As Real;
  area <- base * alto;
End Function

Algorithm Principal
  Write AreaRectangulo(3.0, 4.5);
EndAlgorithm

Subroutine Siete() As Integer
  Write "sin retorno";
EndSubroutine

Algorithm Principal
  Write Siete();
EndAlgorithm
